// Explicit GPU test only with --gpu. --policy-only and --cpu create no queue.
// Float rows/double dots are independently generated by gguf/NumPy, never by
// this candidate's decoder. Real GGUF payloads are bounded streamed slices.
#include "strata/intel/lfm_ops.hpp"
#include "strata/intel/qwen_ops.hpp"
#include "strata/intel/quant.hpp"
#include "strata/intel/device.hpp"
#include "strata/common/utf8_args.hpp"
#include "strata/common/utf8_path.hpp"
#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <memory>
#include <stdexcept>
#include <string>
#include <vector>
namespace {
void need(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
template<class T>T read(std::ifstream& f){T value{};need(bool(f.read(reinterpret_cast<char*>(&value),sizeof value)),"Truncated reference");return value;}
template<class T>std::vector<T> array(std::ifstream& f,size_t count){need(count<=64*1024*1024/sizeof(T),"Oversized reference");std::vector<T> v(count);need(bool(f.read(reinterpret_cast<char*>(v.data()),std::streamsize(count*sizeof(T)))),"Truncated reference array");return v;}
constexpr int ids_ref[3][4]={{0,63,17,42},{63,42,0,17},{17,0,42,63}};
constexpr int extracted_ids[4]={0,63,17,42};
constexpr float poison=123456.f;
struct Case {std::string name;int rows,width,experts;std::vector<uint8_t> raw;std::vector<float> x,values;std::vector<double> dots;};
std::vector<Case> load(const char* path){
    std::ifstream f(strata::paths::native_path(path),std::ios::binary);need(bool(f),"Missing reference");
    need(read<uint64_t>(f)==0x31324634514d464cULL,"Wrong reference magic");const auto count=read<uint32_t>(f);need(count>0&&count<=16,"Wrong reference count");
    std::vector<Case> cases;
    for(uint32_t n=0;n<count;++n){Case c;c.rows=int(read<uint32_t>(f));c.width=int(read<uint32_t>(f));c.experts=int(read<uint32_t>(f));
        const auto inputs=read<uint32_t>(f);const auto bytes=read<uint64_t>(f);const auto names=read<uint32_t>(f);
        need(c.rows>0&&c.rows<=17&&c.width>=256&&c.width<=8192&&c.width%256==0&&(c.experts==1||c.experts==64)&&inputs==4&&names>0&&names<=160,"Invalid reference shape");
        need(bytes==uint64_t(c.experts)*c.rows*(c.width/256)*144,"Invalid Q4_K byte extent");
        auto name=array<char>(f,names);c.name.assign(name.begin(),name.end());c.raw=array<uint8_t>(f,size_t(bytes));c.x=array<float>(f,size_t(4)*c.width);
        c.values=array<float>(f,size_t(c.experts==1?1:4)*c.rows*c.width);c.dots=array<double>(f,size_t(c.experts==1?4:24)*c.rows);cases.push_back(std::move(c));
    }
    need(f.peek()==std::char_traits<char>::eof(),"Trailing reference bytes");return cases;
}
void policy(){
    using strata::intel::lfm_q4_fp32_eligible;
    need(lfm_q4_fp32_eligible(12,1,true),"Candidate T1 gate missing");
    for(int t:{0,2,7,15,16,512,1024})need(!lfm_q4_fp32_eligible(12,t,true),"Candidate changed old multi-token/MKL dispatch");
    for(int type:{0,1,2,8,10,11,14,18,21,22,23,30})need(!lfm_q4_fp32_eligible(type,1,true),"Candidate changed a non-Q4 format");
    need(!lfm_q4_fp32_eligible(12,1,false),"Candidate must default OFF");
}
void cpu(const Case& c){
    const int slices=c.experts==1?1:4;const size_t stride=size_t(c.width/256)*144;
    for(int s=0;s<slices;++s)for(int r=0;r<c.rows;++r)for(int col=0;col<c.width;++col){
        const int expert=c.experts==1?0:extracted_ids[s];
        const float actual=strata::intel::quant::value<12>(c.raw.data()+(size_t(expert)*c.rows+r)*stride,size_t(col));
        const float expected=c.values[(size_t(s)*c.rows+r)*c.width+col];
        need(std::isfinite(actual)&&std::isfinite(expected)&&std::abs(double(actual)-expected)<=2e-6*(1+std::abs(double(expected))),"Scalar Q4_K differs from independent NumPy values");
    }
    for(int route=0;route<(c.experts==1?1:3);++route)for(int separate=0;separate<(c.experts==1?1:2);++separate)for(int p=0;p<4;++p)for(int r=0;r<c.rows;++r){
        const int expert=c.experts==1?0:ids_ref[route][p];int slice=0;
        if(c.experts>1)while(extracted_ids[slice]!=expert)++slice;
        const int source=c.experts==1?p:separate?p:0;double dot=0;
        for(int col=0;col<c.width;++col)dot+=double(c.values[(size_t(slice)*c.rows+r)*c.width+col])*c.x[size_t(source)*c.width+col];
        const size_t index=c.experts==1?size_t(p)*c.rows+r:((size_t(route)*2+separate)*4+p)*c.rows+r;
        need(std::isfinite(c.dots[index])&&std::abs(dot-c.dots[index])<=1e-11*(1+std::abs(c.dots[index])),"Independent FP64 dot/route mismatch");
    }
}
template<class T>struct Buffer {
    sycl::queue& q;T* base;T* p;size_t count;T guard;
    Buffer(sycl::queue& queue,size_t n,T sentinel):q(queue),base(sycl::malloc_shared<T>(n+32,queue)),p(base?base+16:nullptr),count(n),guard(sentinel){need(base!=nullptr,"Numerical allocation failed");std::fill_n(base,n+32,guard);}
    ~Buffer(){try{q.wait();sycl::free(base,q);}catch(...){}}
    void guards()const{for(size_t i=0;i<16;++i)need(base[i]==guard&&p[count+i]==guard,"Input/weight/output outer canary changed");}
};
void gpu(sycl::queue& q,const Case& c){
    Buffer<uint8_t> raw(q,c.raw.size(),0xa5);Buffer<float> x(q,c.x.size(),poison);
    Buffer<int32_t> ids(q,12,-777);Buffer<float> old(q,size_t(4)*c.rows+64,poison),next(q,size_t(4)*c.rows+64,poison);
    std::copy(c.raw.begin(),c.raw.end(),raw.p);std::copy(c.x.begin(),c.x.end(),x.p);
    int checks=0;
    for(int route=0;route<(c.experts==1?1:3);++route)for(int separate=0;separate<(c.experts==1?1:2);++separate)for(int input=0;input<(c.experts==1?4:1);++input){
        std::fill_n(old.p,old.count,poison);std::fill_n(next.p,next.count,poison);
        const size_t active=size_t(c.experts==1?1:4)*c.rows;
        if(c.experts==1){
            strata::intel::quantized_matvec(q,12,raw.p,x.p+size_t(input)*c.width,old.p,c.rows,c.width);
            strata::intel::lfm_q4_fp32_matvec(q,raw.p,x.p+size_t(input)*c.width,next.p,c.rows,c.width).wait_and_throw();
        }else{
            std::copy_n(ids_ref[route],4,ids.p);
            strata::intel::selected_matvec(q,12,raw.p,ids.p,4,x.p,old.p,c.rows,c.width,separate!=0,1);
            strata::intel::lfm_q4_fp32_selected(q,raw.p,ids.p,x.p,next.p,c.rows,c.width,separate!=0).wait_and_throw();
        }
        need(std::memcmp(old.p,next.p,active*sizeof(float))==0,"Candidate differs from baseline FP32 bits; retain default OFF");
        for(size_t i=0;i<active;++i){
            const size_t ref=c.experts==1?size_t(input)*c.rows+i:(size_t(route)*2+separate)*4*c.rows+i;
            need(std::isfinite(next.p[i])&&std::abs(double(next.p[i])-c.dots[ref])<=5e-5*(1+std::abs(c.dots[ref])),"Candidate differs from independent FP64 dot");
        }
        for(size_t i=active;i<old.count;++i)need(old.p[i]==poison&&next.p[i]==poison,"Inactive output changed, including row17 tails");
        need(std::memcmp(raw.p,c.raw.data(),c.raw.size())==0&&std::memcmp(x.p,c.x.data(),c.x.size()*sizeof(float))==0,"Read-only weights/FP32 inputs changed");
        if(c.experts>1)need(std::equal(ids.p,ids.p+4,ids_ref[route]),"Selected expert IDs changed");
        for(size_t i=4;i<ids.count;++i)need(ids.p[i]==-777,"Unused expert ID tail changed");
        raw.guards();x.guards();ids.guards();old.guards();next.guards();++checks;
    }
    bool refused=false;try{strata::intel::lfm_q4_fp32_matvec(q,raw.p+1,x.p,next.p,c.rows,c.width);}catch(const std::invalid_argument&){refused=true;}
    need(refused,"Unaligned Q4 block must be refused before submitting a kernel");
    std::printf("PASS GPU %s rows%d width%d experts%d comparisons%d bit/FP64/all-canary\n",c.name.c_str(),c.rows,c.width,c.experts,checks);
}
}
int main(int argc,char** argv){try{
    strata::paths::Utf8Arguments utf8(argc,argv);argc=utf8.argc();argv=utf8.argv();policy();
    if(argc==2&&std::string(argv[1])=="--policy-only"){std::puts("PASS LFM FP32 Q4 policy; default OFF/T1 only; no queue/model");return 0;}
    need(argc==3&&(std::string(argv[1])=="--cpu"||std::string(argv[1])=="--gpu"),"Usage: --policy-only | --cpu FIXTURE | --gpu FIXTURE (explicit GPU)");
    const auto cases=load(argv[2]);for(const auto& c:cases)cpu(c);
    if(std::string(argv[1])=="--gpu"){sycl::queue q(strata::intel::select_device(0),sycl::property::queue::in_order{});for(const auto& c:cases)gpu(q,c);}
    std::printf("PASS %zu independent cases (%s); no model engine\n",cases.size(),argv[1]+2);return 0;
}catch(const std::exception& e){std::fprintf(stderr,"LFM FP32 Q4 fixture: %s\n",e.what());return 1;}}
